const j2d = (t) => {
    const e = /^(\d{4})-(\d{2})-(\d{2})/.exec(t || "");
    return e ? e[3] + "/" + e[2] : (t || "").slice(0, 5);
  },
  j2pb = (t) =>
    t == null
      ? "\u2013"
      : (t > 0 ? "+" : "") + String(Math.round(t * 10) / 10).replace(".", ",") + " pb",
  j2pc = (t, e = 2) => (t == null || !isFinite(t) ? "\u2013" : jrN(t, e) + "%"),
  j2tv = (t) => "https://www.tradingview.com/chart/?symbol=" + encodeURIComponent(t),
  J2META = 3,
  J2TETO = 4.5;
function j2dec(t, e) {
  if (t == null || e == null) return "";
  const a = Math.round((e - t) * 100);
  return a === 0 ? "manuten\xE7\xE3o" : a < 0 ? "corte de " + -a + " pb" : "alta de " + a + " pb";
}
